module power_handshake_controller (
  input  logic        clk,
  input  logic        rst_n,
  // 處理器輸出訊號
  input  logic        sleep_req,      // CPU 休眠請求
  output logic        sleep_ack,      // 休眠控制器響應確認
  // 控制外圍線路之電源關閉與時脈閘控
  output logic        isolate_en,     // 隔離單元使能
  output logic        power_gate_en,  // 電源網格切斷
  output logic        clock_gate_en   // 時脈切斷
);
  typedef enum logic [1:0] {
    ST_ACTIVE,
    ST_CLOCK_OFF,
    ST_POWER_OFF
  } state_t;

  state_t state, next_state;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= ST_ACTIVE;
    else        state <= next_state;
  end

  always_comb begin
    next_state    = state;
    sleep_ack     = 1'b0;
    isolate_en    = 1'b0;
    power_gate_en = 1'b0;
    clock_gate_en = 1'b0;

    case (state)
      ST_ACTIVE: begin
        if (sleep_req) next_state = ST_CLOCK_OFF;
      end
      ST_CLOCK_OFF: begin
        clock_gate_en = 1'b1;
        isolate_en    = 1'b1;
        if (sleep_req) next_state = ST_POWER_OFF;
        else           next_state = ST_ACTIVE;
      end
      ST_POWER_OFF: begin
        clock_gate_en = 1'b1;
        isolate_en    = 1'b1;
        power_gate_en = 1'b1;
        sleep_ack     = 1'b1;
        if (!sleep_req) next_state = ST_CLOCK_OFF;
      end
    endcase
  end
endmodule

