module apb_timer (
  input  logic        PCLK,
  input  logic        PRESETn,
  input  logic        PSEL,
  input  logic [7:2]  PADDR,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [31:0] PWDATA,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        TIMERINT  // 定時器中斷輸出
);
  // 定義暫存器偏移量
  // 0x00: CTRL [3]TimerIntEn [0]Enable
  // 0x04: VALUE [31:0] Current Value
  // 0x08: RELOAD [31:0] Reload Value
  // 0x0C: INTSTATUS [0] Write 1 to Clear

  logic [31:0] r_ctrl;
  logic [31:0] r_value;
  logic [31:0] r_reload;
  logic        r_intstatus;

  assign PREADY  = 1'b1; // 無等待狀態週邊
  assign PSLVERR = 1'b0; // 始終返回正常

  wire write_en = PSEL && PENABLE && PWRITE;

  // 寫入暫存器控制
  always_ff @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
      r_ctrl      <= 32'h0;
      r_value     <= 32'h0;
      r_reload    <= 32'h0;
      r_intstatus <= 1'b0;
    end else begin
      // 計數下減行為
      if (r_ctrl[0]) begin
        if (r_value == 32'h0) begin
          r_value <= r_reload;
          if (r_ctrl[3]) r_intstatus <= 1'b1; // 中斷使能狀況下觸發計數溢出中斷
        end else begin
          r_value <= r_value - 1;
        end
      end

      // APB 寫入更新暫存器的值
      if (write_en) begin
        case (PADDR[3:2])
          2'b00: r_ctrl   <= PWDATA;
          2'b01: r_value  <= PWDATA;
          2'b10: r_reload <= PWDATA;
          2'b11: if (PWDATA[0]) r_intstatus <= 1'b0; // 清除中斷旗標(Write 1 to Clear)
        endcase
      end
    end
  end

  // 讀取暫存器多路資料復用
  always_comb begin
    PRDATA = 32'h0;
    if (PSEL && !PWRITE) begin
      case (PADDR[3:2])
        2'b00: PRDATA = r_ctrl;
        2'b01: PRDATA = r_value;
        2'b10: PRDATA = r_reload;
        2'b11: PRDATA = {31'h0, r_intstatus};
      endcase
    end
  end

  assign TIMERINT = r_intstatus;
endmodule
